pub enum Msg {
    Ping,
    Hello(String),
}

pub fn decode(bytes: &str) -> Result<Msg, String> {
    if bytes.contains("ping") {
        return Ok(Msg::Ping);
    }
    if let Some(name) = bytes.strip_prefix("v:2|hello|") {
        return Ok(Msg::Hello(name.into()));
    }
    Err("unknown".into())
}

pub fn encode(msg: &Msg) -> String {
    match msg {
        Msg::Ping => "ping".into(),
        Msg::Hello(name) => format!("v:2|hello|{}", name),
    }
}

pub fn ping_roundtrip() -> Result<Msg, String> {
    decode(&encode(&Msg::Ping))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn hello_roundtrips_in_v2_envelope() {
        let msg = Msg::Hello("Ada".into());
        assert_eq!(encode(&msg), "v:2|hello|Ada");
        assert!(matches!(decode(&encode(&msg)), Ok(Msg::Hello(name)) if name == "Ada"));
    }
}

